<?php require '../includes/auth.php';require_role('seller');$sid=seller_profile_id(user()['id']);$s=db()->prepare("SELECT DATE(o.created_at) day,COUNT(*) orders,SUM(so.subtotal) revenue FROM seller_orders so JOIN orders o ON o.id=so.order_id WHERE so.seller_id=? AND so.status='Delivered' GROUP BY DATE(o.created_at) ORDER BY day DESC");$s->execute([$sid]);$rows=$s->fetchAll();$pageTitle='Sales history';require '../includes/header.php';?><div class="page-title"><p class="eyebrow">SELLER ANALYTICS</p><h1>Sales history</h1></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Delivered orders</th><th>Revenue</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['day'])?></td><td><?=$r['orders']?></td><td>₹<?=number_format($r['revenue'],2)?></td></tr><?php endforeach;?></tbody></table></div><?php require '../includes/footer.php'; ?>
